from types import SimpleNamespace

import dspy
from dspy.utils.dummies import DummyLM


def get_weather(city: str) -> str:
    return f"The weather in {city} is sunny"


class NativeToolDummy(DummyLM):
    def __init__(self, adapter):
        super().__init__([{"answer": "unused"}], adapter=adapter)
        self.model = "tool-capable-dummy"

    @property
    def supports_function_calling(self):
        return True

    def forward(self, prompt=None, messages=None, **kwargs):
        return SimpleNamespace(
            choices=[
                SimpleNamespace(
                    message=SimpleNamespace(
                        content=None,
                        tool_calls=[
                            {"function": {"name": "get_weather", "arguments": '{"city": "Paris"}'}}
                        ],
                    ),
                    finish_reason="tool_calls",
                )
            ],
            usage={},
            model=self.model,
        )


class ToolSig(dspy.Signature):
    question: str = dspy.InputField()
    tools: list[dspy.Tool] = dspy.InputField()
    answer: str = dspy.OutputField()
    tool_calls: dspy.ToolCalls = dspy.OutputField()


adapter = dspy.JSONAdapter(use_native_function_calling=True)
lm = NativeToolDummy(adapter)
dspy.configure(lm=lm, adapter=adapter)

predict = dspy.Predict(ToolSig)
result = predict(question="What's the weather in Paris?", tools=[dspy.Tool(get_weather)])
entry = lm.history[-1]
combined_text = "\n".join(str(message["content"]) for message in entry["messages"])

print("MESSAGES:", entry["messages"])
print("TOOLS KWARG:", entry["kwargs"].get("tools"))
print("PARSED RESULT:", result)

assert entry["kwargs"]["tools"][0]["function"]["name"] == "get_weather"
assert "get_weather" not in combined_text
assert result.answer is None
assert result.tool_calls.tool_calls[0].name == "get_weather"
assert result.tool_calls.tool_calls[0].args == {"city": "Paris"}
